'use strict';
// No child_process, Playwright launcher, numeric signaling, or arbitrary RPC input.
const fs = require('node:fs');
const path = require('node:path');
const { createRequire } = require('node:module');
const { Preparation } = require('./prepare-job.cjs');
const { waitIsolation } = require('./isolation-ready.cjs');

function endpoint(value) {
  const u = new URL(value);
  if (u.protocol !== 'ws:' || u.hostname !== '127.0.0.1' || !u.port ||
      !/^\/[a-f0-9-]{36}$/.test(u.pathname) || u.search || u.hash || u.username || u.password) {
    throw new Error('invalid owned inspector endpoint');
  }
  return value;
}

class DefaultContext {
  constructor() { this.ids = new Set(); }
  notification(record) {
    if (record.method === 'Runtime.executionContextCreated') {
      const context = record.params?.context;
      if (context?.auxData?.isDefault !== true) return;
      if (!Number.isInteger(context.id) || context.id <= 0) throw new Error('invalid default Node context');
      this.ids.add(context.id);
      if (this.ids.size !== 1) throw new Error('ambiguous default Node context');
    } else if (record.method === 'Runtime.executionContextDestroyed') {
      this.ids.delete(record.params?.executionContextId);
    } else if (record.method === 'Runtime.executionContextsCleared') this.ids.clear();
  }
  evaluationOptions(expression, mode) {
    if (!['identity', 'menu', 'prepare-start', 'prepare-poll', 'isolation'].includes(mode)) throw new Error('explicit fixed evaluation mode required');
    if (this.ids.size !== 1) throw new Error('unambiguous default Node context required');
    return { expression, contextId: [...this.ids][0], includeCommandLineAPI: true,
      awaitPromise: false, returnByValue: true };
  }
}

class Protocol {
  constructor(send, notify = () => {}) { this.notify = notify; this.send = send; this.next = 1; this.pending = new Map(); }
  call(method, params = {}, timeoutMs = 8000) {
    if (!(timeoutMs > 0 && timeoutMs <= 8000)) return Promise.reject(new Error('CDP timeout bound'));
    if (this.pending.size >= 4) return Promise.reject(new Error('CDP pending bound'));
    const id = this.next++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.pending.delete(id); reject(new Error(`CDP timeout ${method}`)); }, timeoutMs);
      this.pending.set(id, { resolve, reject, timer });
      this.send(JSON.stringify({ id, method, params }));
    });
  }
  receive(bytes) {
    if (Buffer.byteLength(bytes) > 262144) throw new Error('CDP byte bound');
    const record = JSON.parse(bytes);
    if (!record.id) { this.notify(record); return; } // notifications select context, never lifecycle authority
    const p = this.pending.get(record.id);
    if (!p) throw new Error('unexpected CDP reply');
    clearTimeout(p.timer); this.pending.delete(record.id);
    if (record.error || record.result?.exceptionDetails) p.reject(new Error(JSON.stringify(record)));
    else p.resolve(record.result);
  }
  close() {
    for (const p of this.pending.values()) { clearTimeout(p.timer); p.reject(new Error('inspector disconnected')); }
    this.pending.clear();
  }
}

async function run(config, WebSocket) {
  const context = new DefaultContext();
  let socket; let protocol; let connected = false; let prepared = false; let closed = false;
  let diagnosticCount = 0; let diagnosticBytes = 0;
  const diagnose = (value) => {
    const line = Buffer.from(`${JSON.stringify(value)}\n`);
    diagnosticBytes += line.length;
    if (++diagnosticCount > 512 || diagnosticBytes > 131072) throw new Error('CDP diagnostic bound');
    process.stderr.write(line);
  };
  let count = 0; let bytesIn = 0; let bytesOut = 0; let pending = Buffer.alloc(0);
  const emit = (value) => {
    const bytes = Buffer.from(`${JSON.stringify(value)}\n`);
    bytesOut += bytes.length;
    if (bytesOut > 524288) throw new Error('controller output cap');
    process.stdout.write(bytes);
  };
  const evaluate = async (expression, mode, timeoutMs) => {
    const r = await protocol.call('Runtime.evaluate', context.evaluationOptions(expression, mode), timeoutMs);
    if (!Object.hasOwn(r.result || {}, 'value')) throw new Error('CDP missing value');
    return r.result.value;
  };
  const preparation = new Preparation(evaluate, () => Number(process.hrtime.bigint() / 1000000n),
    (ms) => new Promise((resolve) => setTimeout(resolve, ms)), diagnose);
  async function command(c) {
    if (++count > 8 || closed) throw new Error('controller command bound/state');
    if (c.op === 'connect' && !connected) {
      socket = new WebSocket(endpoint(c.endpoint), { maxPayload: 262144, handshakeTimeout: 2000, perMessageDeflate: false });
      protocol = new Protocol((b) => {
        const record = JSON.parse(b); const p = record.params || {};
        diagnose({ kind: 'cdp-outgoing', id: record.id, method: record.method,
          contextId: p.contextId ?? null, includeCommandLineAPI: p.includeCommandLineAPI ?? null,
          awaitPromise: p.awaitPromise ?? null, returnByValue: p.returnByValue ?? null });
        socket.send(b);
      }, (record) => {
        if (['Runtime.executionContextCreated', 'Runtime.executionContextDestroyed', 'Runtime.executionContextsCleared'].includes(record.method)) {
          const c = record.params?.context;
          diagnose({ kind: 'cdp-context', method: record.method,
            id: c?.id ?? record.params?.executionContextId ?? null,
            isDefault: c?.auxData?.isDefault ?? null });
        }
        context.notification(record);
      });
      socket.on('message', (b) => { try { const record = JSON.parse(b.toString());
        if (record.error || record.result?.exceptionDetails) diagnose({ kind: 'cdp-error', record });
        protocol.receive(b.toString()); } catch (e) { protocol.close(); emit({ error: e.message }); socket.terminate(); } });
      socket.on('close', () => protocol.close());
      await new Promise((resolve, reject) => { socket.once('open', resolve); socket.once('error', reject); });
      await protocol.call('Runtime.enable');
      await waitIsolation(evaluate, () => Number(process.hrtime.bigint() / 1000000n),
        (ms) => new Promise((resolve) => setTimeout(resolve, ms)), diagnose);
      const identity = await evaluate('(()=>{const isolation=globalThis.__FREEDOM_KEYCHAIN_ISOLATION_V1__;if(!isolation)throw Error("missing keychain isolation preload");return {pid:process.pid,electron:process.versions.electron,node:process.versions.node,hasElectron:!!require("electron").app,isolation,storageUnavailable:require("electron").safeStorage.isEncryptionAvailable()===false};})()', 'identity');
      if (identity.pid !== config.browserPid || identity.electron !== '43.0.0' || identity.node !== '24.17.0' || !identity.hasElectron || !identity.storageUnavailable || identity.isolation?.policy !== 'safeStorage-unavailable' || identity.isolation?.token !== config.token || identity.isolation?.pid !== config.browserPid) throw new Error('not expected owned Node main context');
      connected = true; return { op: 'connected', identity };
    }
    if (c.op === 'prepare' && connected && !prepared) {
      const mode = config.case === 'quit-idle' ? 'idle' : 'running';
      const fixture = await preparation.start({ mode, token: config.token, expirySeconds: 15 });
      prepared = true; return { op: 'prepared', fixture };
    }
    if (c.op === 'quit' && prepared && c.permit === config.permit) {
      const marker = JSON.stringify(path.join(config.userData, 'native-quit-issued.json'));
      // Evidence is emitted from verified actual B immediately before native action.
      const request = evaluate(`(()=>{const e=require('electron');const f=require('fs');f.writeFileSync(${marker},JSON.stringify({action:'requesting-terminate:',pid:process.pid}),{flag:'wx'});e.Menu.sendActionToFirstResponder('terminate:');f.writeFileSync(${marker},JSON.stringify({action:'terminate:',pid:process.pid,invoked:true,wallMs:Date.now()}));return true;})()`, 'menu');
      // Inspector attachment can itself hold Node exit open. Detach promptly,
      // independently of whether the evaluate response survives actual Quit.
      setTimeout(() => socket.terminate(), 250);
      request.catch(() => {});
      return { op: 'quit-sent' };
    }
    if (c.op === 'disconnect' && connected) {
      closed = true; socket.terminate(); return { op: 'disconnected' };
    }
    throw new Error('invalid/out-of-order controller command');
  }
  let chain = Promise.resolve();
  process.stdin.on('data', (chunk) => {
    bytesIn += chunk.length; pending = Buffer.concat([pending, chunk]);
    if (bytesIn > 8192 || pending.length > 4096) { emit({ error: 'controller input bound' }); process.exitCode = 1; process.stdin.destroy(); socket?.terminate(); return; }
    let at;
    while ((at = pending.indexOf(10)) >= 0) {
      const line = pending.subarray(0, at); pending = pending.subarray(at + 1);
      chain = chain.then(() => command(JSON.parse(line))).then(emit).catch((e) => { emit({ error: e.message }); process.exitCode = 1; });
    }
  });
  process.stdin.on('end', () => { closed = true; protocol?.close(); socket?.terminate(); });
  process.stdout.on('error', () => { closed = true; socket?.terminate(); process.exitCode = 1; });
  const deadline = setTimeout(() => { socket?.terminate(); process.stdin.destroy(); process.exitCode = 1; }, 26000);
  deadline.unref();
}

if (require.main === module) {
  const config = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  if (!path.isAbsolute(config.candidate) || !/^freedom-agent-app-exit-[a-f0-9]{24}$/.test(config.token)) throw new Error('invalid fixed controller config');
  const localRequire = createRequire(path.join(config.candidate, 'package.json'));
  run(config, localRequire('ws')).catch((e) => { process.stderr.write(`${e.stack}\n`); process.exitCode = 1; });
}
module.exports = { endpoint, Protocol, DefaultContext };

'use strict';
const assert = require('node:assert/strict');
const { endpoint, Protocol, DefaultContext } = require('./controller.cjs');
async function main() {
  assert.equal(endpoint('ws://127.0.0.1:1234/11111111-2222-3333-4444-555555555555'), 'ws://127.0.0.1:1234/11111111-2222-3333-4444-555555555555');
  for (const bad of ['ws://localhost:1234/id', 'ws://example.com:1234/id', 'ws://127.0.0.1:12/arbitrary', 'wss://127.0.0.1:1/11111111-2222-3333-4444-555555555555']) assert.throws(() => endpoint(bad));
  const sent = []; const p = new Protocol((b) => sent.push(JSON.parse(b)));
  const first = p.call('Runtime.enable'); const second = p.call('Runtime.evaluate');
  p.receive(JSON.stringify({ id: sent[1].id, result: { result: { value: 'second' } } }));
  p.receive(JSON.stringify({ id: sent[0].id, result: {} }));
  assert.deepEqual(await first, {}); assert.equal((await second).result.value, 'second');
  const third = p.call('Runtime.evaluate');
  p.receive(JSON.stringify({ id: sent[2].id, result: { exceptionDetails: { text: 'synthetic' } } }));
  await assert.rejects(third);
  assert.throws(() => p.receive('{bad'));
  assert.throws(() => p.receive(JSON.stringify({ id: 999, result: {} })));
  assert.throws(() => p.receive('x'.repeat(262145)));
  const pending = p.call('Runtime.enable'); p.close(); await assert.rejects(pending);
  let contextAssertions = 0;
  const check = (fn) => { fn(); contextAssertions++; };
  const context = new DefaultContext();
  const notifications = new Protocol(() => {}, (record) => context.notification(record));
  check(() => assert.throws(() => context.evaluationOptions('fixed', 'identity')));
  notifications.receive(JSON.stringify({ method: 'Runtime.executionContextCreated', params: { context: { id: 1, auxData: { isDefault: false } } } }));
  check(() => assert.throws(() => context.evaluationOptions('fixed', 'identity')));
  notifications.receive(JSON.stringify({ method: 'Runtime.consoleAPICalled', params: {} }));
  check(() => assert.equal(context.ids.size, 0));
  notifications.receive(JSON.stringify({ method: 'Runtime.executionContextCreated', params: { context: { id: 7, auxData: { isDefault: true } } } }));
  check(() => assert.deepEqual(context.evaluationOptions('fixed', 'identity'), { expression: 'fixed', contextId: 7, includeCommandLineAPI: true, awaitPromise: false, returnByValue: true }));
  const actualSent = [];
  const optionsProtocol = new Protocol((b) => actualSent.push(JSON.parse(b)));
  const evalPromise = optionsProtocol.call('Runtime.evaluate', context.evaluationOptions('fixed', 'identity'));
  check(() => assert.deepEqual(actualSent[0].params, context.evaluationOptions('fixed', 'identity')));
  optionsProtocol.receive(JSON.stringify({ id: actualSent[0].id, result: { result: { value: 'ok' } } }));
  check(() => assert.equal(actualSent[0].method, 'Runtime.evaluate'));
  await evalPromise;
  check(() => assert.throws(() => notifications.receive(JSON.stringify({ method: 'Runtime.executionContextCreated', params: { context: { id: 8, auxData: { isDefault: true } } } }))));
  check(() => assert.throws(() => context.evaluationOptions('fixed', 'identity')));
  context.notification({ method: 'Runtime.executionContextsCleared' });
  check(() => assert.throws(() => context.evaluationOptions('fixed', 'identity')));
  context.notification({ method: 'Runtime.executionContextCreated', params: { context: { id: 9, auxData: { isDefault: true } } } });
  context.notification({ method: 'Runtime.executionContextDestroyed', params: { executionContextId: 9 } });
  check(() => assert.throws(() => context.evaluationOptions('fixed', 'identity')));
  for (const id of [0, -1, '1', null]) check(() => assert.throws(() => context.notification({ method: 'Runtime.executionContextCreated', params: { context: { id, auxData: { isDefault: true } } } })));
  // Runtime.enable may deliver the notification before its correlated reply.
  const ordered = []; const c2 = new DefaultContext();
  const p2 = new Protocol((b) => ordered.push(JSON.parse(b)), (r) => c2.notification(r));
  const enabled = p2.call('Runtime.enable');
  p2.receive(JSON.stringify({ method: 'Runtime.executionContextCreated', params: { context: { id: 10, auxData: { isDefault: true } } } }));
  p2.receive(JSON.stringify({ id: ordered[0].id, result: {} }));
  await enabled;
  check(() => assert.equal(c2.evaluationOptions('fixed', 'identity').contextId, 10));
  check(() => assert.equal(c2.evaluationOptions('fixed-menu', 'menu').awaitPromise, false));
  check(() => assert.equal(c2.evaluationOptions('fixed-prepare', 'prepare-start').awaitPromise, false));
  check(() => assert.equal(c2.evaluationOptions('fixed-id', 'identity').awaitPromise, false));
  check(() => assert.throws(() => c2.evaluationOptions('fixed')));
  check(() => assert.throws(() => c2.evaluationOptions('fixed', 'arbitrary')));
  check(() => assert.equal(c2.evaluationOptions('fixed-poll', 'prepare-poll').awaitPromise, false));
  console.log(JSON.stringify({ assertionsPassed: 12 + contextAssertions, priorAssertions: 12, contextAssertions, sockets: 0, spawns: 0, signals: 0, scope: 'pure endpoint/framing/context/evaluation-option mocks' }));
}
main().catch((e) => { console.error(e); process.exitCode = 1; });

'use strict';
// Inspector can accept requests inside Electron's Module._preloadModules.
// Wait for the real fixed preload marker; never manufacture it or call storage early.
async function waitIsolation(evaluate, now, sleep, diagnose) {
  const deadline = now() + 1000;
  let polls = 0;
  for (; polls < 40; polls++) {
    const left = deadline - now();
    if (left <= 0) break;
    const value = await evaluate('globalThis.__FREEDOM_KEYCHAIN_ISOLATION_V1__ || null', 'isolation', Math.min(250, left));
    if (now() >= deadline) break;
    if (value !== null) {
      if (value.v !== 1 || value.policy !== 'safeStorage-unavailable' || value.realKeychainQualified !== false || value.providerQualified !== false) throw new Error('invalid isolation marker');
      diagnose({ kind: 'isolation-ready', polls: polls + 1 });
      return value; // exact token/PID/storage=false still checked by identity expression
    }
    await sleep(Math.min(25, Math.max(0, deadline - now())));
  }
  throw new Error('fixed keychain preload readiness deadline');
}
module.exports = { waitIsolation };

'use strict';
const assert = require('node:assert/strict');
const { waitIsolation } = require('./isolation-ready.cjs');
const { DefaultContext } = require('./controller.cjs');
async function main() {
  const marker = { v: 1, policy: 'safeStorage-unavailable', realKeychainQualified: false, providerQualified: false };
  let checks = 0;
  for (const delay of [0, 3]) {
    let time = 0; let calls = 0; let pending = 0; let peak = 0;
    const result = await waitIsolation(async (expression, mode, timeout) => {
      pending++; peak=Math.max(peak,pending);
      assert.equal(expression,'globalThis.__FREEDOM_KEYCHAIN_ISOLATION_V1__ || null');
      assert.equal(mode,'isolation');assert.ok(timeout<=250 && timeout>0);calls++;
      pending--;return calls>delay?marker:null;
    },()=>time,async(ms)=>{time+=ms;},()=>{});
    assert.equal(result,marker);assert.equal(calls,delay+1);assert.equal(peak,1);checks++;
  }
  let time=0;let calls=0;
  await assert.rejects(waitIsolation(async()=>{calls++;return null;},()=>time,async(ms)=>{time+=ms;},()=>{}),/readiness deadline/);
  assert.equal(time,1000);assert.equal(calls,40);checks++;
  await assert.rejects(waitIsolation(async()=>({v:1}),()=>0,async()=>{},()=>{}),/invalid isolation marker/);checks++;
  await assert.rejects(waitIsolation(async()=>{throw Error('CDP timeout');},()=>0,async()=>{},()=>{}),/CDP timeout/);checks++;
  time=0;
  await assert.rejects(waitIsolation(async()=>{time=1001;return marker;},()=>time,async()=>{},()=>{}),/readiness deadline/);checks++;
  const context=new DefaultContext();context.ids.add(1);
  assert.equal(context.evaluationOptions('fixed','isolation').awaitPromise,false);checks++;
  console.log(JSON.stringify({pureCasesPassed:checks,sockets:0,processes:0,signals:0}));
}
main().catch((e)=>{console.error(e);process.exitCode=1;});

'use strict';
// Test-only capability removal; no native safeStorage method is called.
function installUnavailable({ electron, fs, path, process: proc, filename, host }) {
  const fail = () => { throw new Error('fixed credential-free keychain isolation gate failed'); };
  if (proc.env.FREEDOM_TEST_MODE !== '1' || proc.env.ELECTRON_RUN_AS_NODE || proc.type !== 'browser') fail();
  const root = path.dirname(path.dirname(filename));
  if (filename !== path.join(root, 'harness/keychain-preload.cjs') || !root.startsWith('/private/tmp/freedom-keychain-isolated-') ||
      fs.realpathSync(filename) !== filename || proc.cwd() !== path.join(root, 'candidate')) fail();
  const user = proc.env.FREEDOM_TEST_USER_DATA; const tmp = proc.env.TMPDIR;
  if (!user || !tmp || !path.isAbsolute(user) || !path.isAbsolute(tmp) ||
      fs.realpathSync(user) !== user || fs.realpathSync(tmp) !== tmp || path.dirname(user) !== tmp ||
      proc.env.HOME !== user || !path.basename(user).startsWith('freedom-agent-app-exit-') ||
      !tmp.startsWith(path.join(root, 'execution-')) || path.basename(tmp) !== 'tmp') fail();
  const caseDir = path.dirname(tmp); const st = fs.statSync(user);
  if (st.uid !== proc.getuid() || (st.mode & 0o077) !== 0) fail();
  const args = proc.argv.filter((arg) => arg.startsWith('--freedom-owner-token='));
  if (args.length !== 1) fail();
  const token = args[0].slice('--freedom-owner-token='.length);
  if (!/^freedom-agent-app-exit-[a-f0-9]{24}$/.test(token)) fail();
  const intentPath = path.join(caseDir, 'intent.json');
  if (fs.statSync(intentPath).size > 8192) fail();
  const intent = JSON.parse(fs.readFileSync(intentPath, 'utf8'));
  if (intent.token !== token || intent.userData !== user || intent.tmpdir !== tmp || intent.beforeLaunch !== true ||
      !['quit-idle','quit-running','main-loss','supervisor-loss'].includes(intent.case)) fail();
  if (host.__FREEDOM_KEYCHAIN_ISOLATION_V1__) fail();
  const unavailable = () => Object.assign(new Error('Credential-free lifecycle test: secure storage unavailable'), { code: 'FREEDOM_TEST_STORAGE_UNAVAILABLE' });
  const blocked = () => { throw unavailable(); };
  const rejected = () => Promise.reject(unavailable());
  const methods = { isEncryptionAvailable: () => false, isAsyncEncryptionAvailable: () => Promise.resolve(false),
    encryptString: blocked, decryptString: blocked, encryptStringAsync: rejected, decryptStringAsync: rejected,
    setUsePlainTextEncryption: blocked };
  const storage = electron.safeStorage;
  if (!storage) fail();
  for (const [name, value] of Object.entries(methods)) {
    if (typeof storage[name] !== 'function') fail();
    Object.defineProperty(storage, name, { value, enumerable: true, configurable: false, writable: false });
  }
  const marker = Object.freeze({ v: 1, policy: 'safeStorage-unavailable', token, pid: proc.pid,
    realKeychainQualified: false, providerQualified: false });
  Object.defineProperty(host, '__FREEDOM_KEYCHAIN_ISOLATION_V1__', { value: marker, configurable: false, writable: false });
  fs.writeFileSync(path.join(user, 'keychain-isolation.json'), JSON.stringify(marker), { flag: 'wx', mode: 0o600 });
  return marker;
}
module.exports = { installUnavailable };

'use strict';
const assert = require('node:assert/strict');
const path = require('node:path');
const fs = require('node:fs');
const vm = require('node:vm');
const { installUnavailable } = require('./keychain-policy.cjs');
const root = '/private/tmp/freedom-keychain-isolated-mock/attempt01';
const tmp = root + '/execution-mock/quit-running-mock/tmp';
const user = tmp + '/freedom-agent-app-exit-mock';
const token = 'freedom-agent-app-exit-' + 'a'.repeat(24);
function fake() {
  const calls = []; const writes = [];
  const storage = Object.fromEntries(['isEncryptionAvailable','isAsyncEncryptionAvailable','encryptString','decryptString','encryptStringAsync','decryptStringAsync','setUsePlainTextEncryption'].map((k) => [k, () => { calls.push(k); throw new Error('native method must never forward'); }]));
  const intent = { token, userData: user, tmpdir: tmp, beforeLaunch: true, case: 'quit-running' };
  const proc = { type: 'browser', pid: 123, getuid: () => 501, cwd: () => root+'/candidate', argv: ['Electron','--freedom-owner-token='+token],
    env: { FREEDOM_TEST_MODE: '1', FREEDOM_TEST_USER_DATA: user, HOME: user, TMPDIR: tmp } };
  return { electron: { safeStorage: storage, app: { untouched: true } }, fs: { realpathSync: (s) => s,
    statSync: () => ({ uid: 501, mode: 0o700, size: 100 }), readFileSync: () => JSON.stringify(intent),
    writeFileSync: (...args) => writes.push(args) }, path, process: proc, filename: root+'/harness/keychain-preload.cjs', host: {}, calls, writes, intent };
