  assert.equal(s.electron.safeStorage.isEncryptionAvailable(), false); assertions++;
  assert.equal(await s.electron.safeStorage.isAsyncEncryptionAvailable(), false); assertions++;
  for (const k of ['encryptString','decryptString','setUsePlainTextEncryption']) { assert.throws(() => s.electron.safeStorage[k]('synthetic'), { code: 'FREEDOM_TEST_STORAGE_UNAVAILABLE' }); assertions++; }
  for (const k of ['encryptStringAsync','decryptStringAsync']) { await assert.rejects(s.electron.safeStorage[k]('synthetic'), { code: 'FREEDOM_TEST_STORAGE_UNAVAILABLE' }); assertions++; }
  assert.deepEqual(s.calls, []); assertions++;
  assert.equal(s.electron.app, app); assertions++;
  assert.equal(marker.realKeychainQualified, false); assert.equal(marker.providerQualified, false); assertions+=2;
  assert.equal(s.writes[0][0],user+'/keychain-isolation.json'); assert.equal(s.writes[0][2].mode,0o600); assertions+=2;
  assert.throws(() => installUnavailable(s)); assertions++;
  for (const change of [
    (f) => { f.process.env.FREEDOM_TEST_MODE='0'; },
    (f) => { f.process.env.ELECTRON_RUN_AS_NODE='1'; },
    (f) => { f.process.type='renderer'; },
    (f) => { f.process.env.HOME='/unowned'; },
    (f) => { f.process.env.TMPDIR='/unowned'; },
    (f) => { f.process.argv=[]; },
    (f) => { f.process.argv.push('--freedom-owner-token='+token); },
    (f) => { f.intent.token='wrong'; },
    (f) => { f.intent.beforeLaunch=false; },
    (f) => { f.intent.case='arbitrary'; },
    (f) => { f.process.cwd=()=>'/other'; },
    (f) => { f.filename=root+'/candidate/src/main/preload.cjs'; },
    (f) => { f.fs.realpathSync=()=>'/symlink-target'; },
    (f) => { f.fs.statSync=()=>({uid:999,mode:0o700,size:100}); },
    (f) => { f.fs.statSync=()=>({uid:501,mode:0o777,size:100}); },
    (f) => { f.fs.statSync=()=>({uid:501,mode:0o700,size:8193}); },
  ]) { const f=fake(); change(f); assert.throws(()=>installUnavailable(f)); assert.deepEqual(f.calls,[]); assert.equal(f.writes.length,0); assertions+=3; }
  const wrapper = fs.readFileSync(path.join(__dirname,'keychain-preload.cjs'),'utf8');
