"""Native adapter methods with fake libraries/queues only; no Native() construction."""
import unittest
from types import SimpleNamespace
import select
from native import Native, NativeError


class Tests(unittest.TestCase):
    def test_child_count_and_tail(self):
        n=Native.__new__(Native);n.recheck=lambda _:None
        for rc,values in [(1,[123]),(21,[]),(-1,[]),(2,[123,123]),(1,[123,999])]:
            def listing(_pid,ids,_size):
                for i,v in enumerate(values):ids[i]=v
                return rc
            n.lib=SimpleNamespace(proc_listchildpids=listing)
            if values==[123]:self.assertEqual(n.children({'pid':100}),[123])
            else:
                with self.assertRaises(NativeError):n.children({'pid':100})

    def test_missing_status_never_zero(self):
        n=Native.__new__(Native);n.entries={'C':{'key':1,'role':'C','identity':{'pid':123}}};n.events={}
        event=SimpleNamespace(udata=1,ident=123,flags=0,fflags=select.KQ_NOTE_EXIT,data=0)
        n.kq=SimpleNamespace(control=lambda *_:[event])
        self.assertFalse(n.poll()['C']['statusKnown']);self.assertIsNone(n.events['C']['rawStatus'])

    def test_status_fourteen_preserved(self):
        n=Native.__new__(Native);n.entries={'C':{'key':1,'role':'C','identity':{'pid':123}}};n.events={}
        event=SimpleNamespace(udata=1,ident=123,flags=0,fflags=select.KQ_NOTE_EXIT|0x04000000,data=14)
        n.kq=SimpleNamespace(control=lambda *_:[event])
        self.assertEqual(n.poll()['C']['rawStatus'],14)

    def test_matching_key_wrong_pid_rejected(self):
        n=Native.__new__(Native);n.entries={'C':{'key':1,'role':'C','identity':{'pid':123}}};n.events={}
        event=SimpleNamespace(udata=1,ident=999,flags=0,fflags=select.KQ_NOTE_EXIT|0x04000000,data=0)
        n.kq=SimpleNamespace(control=lambda *_:[event])
        with self.assertRaisesRegex(NativeError,'PID/key mismatch'):n.poll()
        self.assertEqual(n.events,{})

    def test_no_c_signal(self):
        n=Native.__new__(Native);n._tokens={'C':'synthetic'}
        with self.assertRaises(RuntimeError):n.signal('C',9)

    def test_register_retains_identity_before_failure(self):
        n=Native.__new__(Native);n.entries={}
        def fail(*_):raise OSError(1,'synthetic permission failure')
        n.kq=SimpleNamespace(control=fail)
        with self.assertRaises(NativeError):n.register('S',{'pid':123})
        self.assertEqual(n.entries['S']['identity'],{'pid':123})
        self.assertFalse(n.entries['S']['statusRequested'])


if __name__=='__main__':unittest.main(verbosity=2)

"""Pure campaign selection: no native constructor, socket, child or signal."""
import unittest
from types import SimpleNamespace
from watchdog import authorize_scope, campaign_cases, APPROVED_REQUEST, APPROVED_CASES

class Tests(unittest.TestCase):
    def review(self): return dict(executionReady=True, cases=list(APPROVED_CASES), request=APPROVED_REQUEST)
    def test_exact_scope(self): authorize_scope(APPROVED_CASES, APPROVED_REQUEST, self.review())
    def test_wrong_cases(self):
        for cases in ((), ('quit-idle',), tuple(reversed(APPROVED_CASES))):
            with self.assertRaises(AssertionError): authorize_scope(cases, APPROVED_REQUEST, self.review())
    def test_wrong_request(self):
        with self.assertRaises(AssertionError): authorize_scope(APPROVED_CASES, 'old', self.review())
    def test_wrong_review(self):
        for review in (None, {}, dict(self.review(), executionReady=False), dict(self.review(), cases=['quit-idle']), dict(self.review(), request='old')):
            with self.assertRaises(AssertionError): authorize_scope(APPROVED_CASES, APPROVED_REQUEST, review)
    def test_four_once_in_order(self):
        calls=[]; saved=[]
        def factory(case, _root):
            calls.append(case)
            return SimpleNamespace(run=lambda:dict(case=case, passed=True))
        results=campaign_cases('mock',factory,lambda:0,lambda rows:saved.append(len(rows)))
        self.assertEqual(calls,list(APPROVED_CASES)); self.assertEqual(len(results),4); self.assertEqual(saved,[1,2,3,4])
    def test_first_failure_stops(self):
        for fail_at in range(4):
            calls=[]
            def factory(case,_root):
                calls.append(case)
                return SimpleNamespace(run=lambda:dict(passed=len(calls)!=fail_at+1))
            rows=campaign_cases('mock',factory,lambda:0,lambda _:None)
            self.assertEqual(calls,list(APPROVED_CASES[:fail_at+1])); self.assertEqual(len(rows),fail_at+1)
    def test_exception_no_retry(self):
        calls=[]
        def factory(*args):
            calls.append(args); raise RuntimeError('setup failure')
        with self.assertRaises(RuntimeError): campaign_cases('mock',factory,lambda:0,lambda _:None)
        self.assertEqual(len(calls),1)

if __name__ == '__main__': unittest.main(verbosity=2)

"""Pure log-parser tests; fake file object only, no live Case construction."""
import unittest
from types import SimpleNamespace
from watchdog import shutdown_log

PHASES=['before_quit','agent_dispose_started','agent_dispose_finished','windows_close_started','windows_close_finished','nodes_stop_started','final_quit_requested','will_quit','quit']


class Root:
    def __init__(self,text):self.text=text
    def __truediv__(self,_):return SimpleNamespace(exists=lambda:True,stat=lambda:SimpleNamespace(st_size=len(self.text)),read_text=lambda **_:self.text)


class Tests(unittest.TestCase):
    def test_ordered(self):
        log='\n'.join("event: '%s'"%x for x in PHASES)
        self.assertEqual(shutdown_log(Root(log)),(True,False))
    def test_wrong_order(self):
        log='\n'.join("event: '%s'"%x for x in reversed(PHASES))
        self.assertEqual(shutdown_log(Root(log)),(False,False))
    def test_actual_service_deadline_warning(self):
        log='[AgentWorkspace] Shutdown deadline reached; workspace cleanup remains uncertain'
        self.assertEqual(shutdown_log(Root(log)),(False,True))


if __name__=='__main__':unittest.main(verbosity=2)

