def git_object(kind,data): return hashlib.sha1(kind+b' '+str(len(data)).encode()+b'\0'+data).digest()
def identity(p):
 if p.is_symlink(): return git_object(b'blob',os.readlink(p).encode())
 if p.is_dir():
  entries=[]
  for c in sorted(p.iterdir(),key=lambda c:c.name+('/' if c.is_dir() and not c.is_symlink() else '')):
   mode=b'120000' if c.is_symlink() else b'40000' if c.is_dir() else b'100755' if c.stat().st_mode & stat.S_IXUSR else b'100644'
   entries.append(mode+b' '+c.name.encode()+b'\0'+identity(c))
  return git_object(b'tree',b''.join(entries))
 return git_object(b'blob',p.read_bytes())
expected=json.loads((root/'source-proof.json').read_text()); actual={k:identity(candidate/k).hex() for k in expected['sourceSubtrees']}
assert actual==expected['sourceSubtrees'],actual
native={}
